cerebro.package.json:
{
  "name": "cerebro",
  "version": "0.2.0",
  "private": true,
  "description": "Personal knowledge clipper with citation-backed chat",
  "scripts": {
    "dev": "CONVEX_AGENT_MODE=anonymous npx convex dev",
    "deploy": "npx convex deploy",
    "typecheck": "tsc --noEmit -p convex/tsconfig.json",
    "eval:seed": "node --env-file=.env.local eval/seed.mjs",
    "eval:retrieval": "node --env-file=.env.local eval/run.mjs --seed"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/RaapTechllc/cerebro.git"
  },
  "license": "UNLICENSED",
  "dependencies": {
    "@types/node": "^26.0.1",
    "convex": "^1.42.1",
    "typescript": "^6.0.3"
  }
}
